<?php
namespace FeedWriter; use \DateTime; use \DateTimeInterface; /**
 * Universal Feed Writer class
 *
 * Generate RSS 1.0, RSS2.0 and ATOM Feeds
 *
 * @package     UniversalFeedWriter
 * @author      Anis uddin Ahmad <anisniit@gmail.com>
 * @link        http://www.ajaxray.com/projects/rss
 */
abstract class Feed { const RSS1 = 'RSS 1.0'; const RSS2 = 'RSS 2.0'; const ATOM = 'ATOM'; const VERSION = '1.1.0'; private $channels = array(); private $items = array(); private $data = array(); private $CDATAEncoding = array(); private $namespaces = array(); private $version = null; private $encoding = 'utf-8'; protected function __construct($version = Feed::RSS2) { $this->version = $version; $this->setTitle($version . ' Feed'); $this->namespaces['content'] = 'http://purl.org/rss/1.0/modules/content/'; $this->namespaces['wfw'] = 'http://wellformedweb.org/CommentAPI/'; $this->namespaces['atom'] = 'http://www.w3.org/2005/Atom'; $this->namespaces['rdf'] = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#'; $this->namespaces['rss1'] = 'http://purl.org/rss/1.0/'; $this->namespaces['dc'] = 'http://purl.org/dc/elements/1.1/'; $this->namespaces['sy'] = 'http://purl.org/rss/1.0/modules/syndication/'; $this->addCDATAEncoding(array('description', 'content:encoded', 'summary')); } public function setPagination($nextURL = null, $previousURL = null, $firstURL = null, $lastURL = null) { if (empty($nextURL) && empty($previousURL) && empty($firstURL) && empty($lastURL)) throw new \LogicException('At least one URL must be specified for pagination to work.'); if (!empty($nextURL)) $this->setAtomLink($nextURL, 'next'); if (!empty($previousURL)) $this->setAtomLink($previousURL, 'previous'); if (!empty($firstURL)) $this->setAtomLink($firstURL, 'first'); if (!empty($lastURL)) $this->setAtomLink($lastURL, 'last'); return $this; } public function addGenerator() { if ($this->version == Feed::ATOM) $this->setChannelElement('atom:generator', 'FeedWriter', array('uri' => 'https://github.com/mibe/FeedWriter')); else if ($this->version == Feed::RSS2) $this->setChannelElement('generator', 'FeedWriter'); else throw new InvalidOperationException('The generator element is not supported in RSS1 feeds.'); return $this; } public function addNamespace($prefix, $uri) { if (empty($prefix)) throw new \InvalidArgumentException('The prefix may not be emtpy or NULL.'); if (empty($uri)) throw new \InvalidArgumentException('The uri may not be empty or NULL.'); $this->namespaces[$prefix] = $uri; return $this; } public function setChannelElement($elementName, $content, ?array $attributes = null, $multiple = false) { if (empty($elementName)) throw new \InvalidArgumentException('The element name may not be empty or NULL.'); if (!is_string($elementName)) throw new \InvalidArgumentException('The element name must be a string.'); $entity['content'] = $content; $entity['attributes'] = $attributes; if ($multiple === TRUE) $this->channels[$elementName][] = $entity; else $this->channels[$elementName] = $entity; return $this; } public function setChannelElementsFromArray(array $elementArray) { foreach ($elementArray as $elementName => $content) { $this->setChannelElement($elementName, $content); } return $this; } public function getMIMEType() { switch ($this->version) { case Feed::RSS2 : $mimeType = "application/rss+xml"; break; case Feed::RSS1 : $mimeType = "application/rdf+xml"; break; case Feed::ATOM : $mimeType = "application/atom+xml"; break; default : $mimeType = "text/xml"; } return $mimeType; } public function printFeed($useGenericContentType = false) { if (!is_bool($useGenericContentType)) throw new \InvalidArgumentException('The useGenericContentType parameter must be boolean.'); $contentType = "text/xml"; if (!$useGenericContentType) { $contentType = $this->getMIMEType(); } $feed = $this->generateFeed(); header("Content-Type: " . $contentType . "; charset=" . $this->encoding); echo $feed; } public function generateFeed() { if ($this->version != Feed::ATOM && !array_key_exists('link', $this->channels)) throw new InvalidOperationException('RSS1 & RSS2 feeds need a link element. Call the setLink method before this method.'); return $this->makeHeader() . $this->makeChannels() . $this->makeItems() . $this->makeFooter(); } public function createNewItem() { $Item = new Item($this->version); return $Item; } public function addCDATAEncoding(array $tags) { $this->CDATAEncoding = array_merge($this->CDATAEncoding, $tags); return $this; } public function getCDATAEncoding() { return $this->CDATAEncoding; } public function removeCDATAEncoding(array $tags) { $this->CDATAEncoding = array_values(array_diff($this->CDATAEncoding, $tags)); } public function addItem(Item $feedItem) { if ($feedItem->getVersion() != $this->version) { $msg = sprintf('Feed type mismatch: This instance can handle %s feeds only, but item for %s feeds given.', $this->version, $feedItem->getVersion()); throw new \InvalidArgumentException($msg); } $this->items[] = $feedItem; return $this; } public function setEncoding($encoding) { if (empty($encoding)) throw new \InvalidArgumentException('The encoding may not be empty or NULL.'); if (!is_string($encoding)) throw new \InvalidArgumentException('The encoding must be a string.'); $this->encoding = $encoding; return $this; } public function setTitle($title) { if (empty($title)) throw new \InvalidArgumentException('The title may not be empty or NULL.'); return $this->setChannelElement('title', $title); } public function setDate($date) { if ($this->version == Feed::RSS1) throw new InvalidOperationException('The publication date is not supported in RSS1 feeds.'); $format = $this->version == Feed::ATOM ? \DATE_ATOM : \DATE_RSS; if ($date instanceof DateTimeInterface || $date instanceof DateTime) $date = $date->format($format); else if(is_numeric($date) && $date >= 0) $date = date($format, $date); else if (is_string($date)) { $timestamp = strtotime($date); if ($timestamp === FALSE) throw new \InvalidArgumentException('The given date was not parseable.'); $date = date($format, $timestamp); } else throw new \InvalidArgumentException('The given date is not an implementation of DateTimeInterface, a UNIX timestamp or a date string.'); if ($this->version == Feed::ATOM) $this->setChannelElement('updated', $date); else $this->setChannelElement('lastBuildDate', $date); return $this; } public function setDescription($description) { if (empty($description)) throw new \InvalidArgumentException('The description may not be empty or NULL.'); if ($this->version != Feed::ATOM) $this->setChannelElement('description', $description); else $this->setChannelElement('subtitle', $description); return $this; } public function setLink($link) { if (empty($link)) throw new \InvalidArgumentException('The link may not be empty or NULL.'); if ($this->version == Feed::ATOM) $this->setAtomLink($link); else $this->setChannelElement('link', $link); return $this; } public function setAtomLink($href, $rel = null, $type = null, $hreflang = null, $title = null, $length = null) { $data = array('href' => $href); if ($rel != null) { if (!is_string($rel) || empty($rel)) throw new \InvalidArgumentException('rel parameter must be a string and a valid relation identifier.'); $data['rel'] = $rel; } if ($type != null) { if (!is_string($type) || preg_match('/.+\/.+/', $type) != 1) throw new \InvalidArgumentException('type parameter must be a string and a MIME type.'); $data['type'] = $type; } if ($hreflang != null) { if (!is_string($hreflang) || preg_match('/[A-Za-z]{1,8}(-[A-Za-z0-9]{1,8})*/', $hreflang) != 1) throw new \InvalidArgumentException('hreflang parameter must be a string and a valid language code.'); $data['hreflang'] = $hreflang; } if ($title != null) { if (!is_string($title) || empty($title)) throw new \InvalidArgumentException('title parameter must be a string and not empty.'); $data['title'] = $title; } if ($length != null) { if (!is_int($length) || $length < 0) throw new \InvalidArgumentException('length parameter must be a positive integer.'); $data['length'] = (string) $length; } if ($this->version == Feed::ATOM) { foreach ($this->channels as $key => $value) { if ($key != 'atom:link') continue; foreach ($value as $linkItem) { $attrib = $linkItem['attributes']; if (@$attrib['rel'] == 'alternate' && @$attrib['hreflang'] == $hreflang && @$attrib['type'] == $type) throw new InvalidOperationException('The feed must not contain more than one link element with a' . ' relation of "alternate" that has the same combination of type and hreflang attribute values.'); } } } return $this->setChannelElement('atom:link', '', $data, true); } public function setSelfLink($url) { return $this->setAtomLink($url, 'self', $this->getMIMEType()); } public function setImage($url, $title = null, $link = null) { if (!is_string($url) || empty($url)) throw new \InvalidArgumentException('url parameter must be a string and may not be empty or NULL.'); if ($this->version != Feed::ATOM) { if (!is_string($title) || empty($title)) throw new \InvalidArgumentException('title parameter must be a string and may not be empty or NULL.'); if (!is_string($link) || empty($link)) throw new \InvalidArgumentException('link parameter must be a string and may not be empty or NULL.'); $data = array('title'=>$title, 'link'=>$link, 'url'=>$url); $name = 'image'; } else { $name = 'logo'; $data = $url; } if ($this->version == Feed::RSS1) { $this->data['Image'] = $data; return $this->setChannelElement($name, '', array('rdf:resource' => $url), false); } else return $this->setChannelElement($name, $data); } public function setChannelAbout($url) { if ($this->version != Feed::RSS1) throw new InvalidOperationException("This method is only supported in RSS1 feeds."); if (empty($url)) throw new \InvalidArgumentException('The about URL may not be empty or NULL.'); if (!is_string($url)) throw new \InvalidArgumentException('The about URL must be a string.'); $this->data['ChannelAbout'] = $url; return $this; } public static function uuid($key = null, $prefix = '') { $key = ($key == null) ? uniqid(rand()) : $key; $chars = md5($key); $uuid = substr($chars,0,8) . '-'; $uuid .= substr($chars,8,4) . '-'; $uuid .= substr($chars,12,4) . '-'; $uuid .= substr($chars,16,4) . '-'; $uuid .= substr($chars,20,12); return $prefix . $uuid; } public static function filterInvalidXMLChars($string, $replacement = '_') { $result = preg_replace('/[^\x{0009}\x{000a}\x{000d}\x{0020}-\x{D7FF}\x{E000}-\x{FFFD}\x{10000}-\x{10FFFF}]+/u', $replacement, $string); if ($result == NULL && preg_last_error() == PREG_BAD_UTF8_ERROR) $result = preg_replace('/[^\x09\x0a\x0d\x20-\xFF]+/', $replacement, $string); if ($result == NULL) $result = $string; return $result; } private function getNamespacePrefixes() { $prefixes = array(); $tags = array_keys($this->channels); foreach ($this->items as $item) { foreach (array_keys($item->getElements()) as $key) { if (!in_array($key, $tags)) { $tags[] = $key; } } } foreach ($tags as $tag) { $elements = explode(':', $tag); if (count($elements) != 2) continue; $prefixes[] = $elements[0]; } return array_unique($prefixes); } private function makeHeader() { $out = '<?xml version="1.0" encoding="'.$this->encoding.'" ?>' . PHP_EOL; $prefixes = $this->getNamespacePrefixes(); $attributes = array(); $tagName = ''; $defaultNamespace = ''; if ($this->version == Feed::RSS2) { $tagName = 'rss'; $attributes['version'] = '2.0'; } elseif ($this->version == Feed::RSS1) { $tagName = 'rdf:RDF'; $prefixes[] = 'rdf'; $defaultNamespace = $this->namespaces['rss1']; } elseif ($this->version == Feed::ATOM) { $tagName = 'feed'; $defaultNamespace = $this->namespaces['atom']; $prefixes = array_flip($prefixes); unset($prefixes['atom']); $prefixes = array_flip($prefixes); } foreach ($prefixes as $prefix) { if (!isset($this->namespaces[$prefix])) throw new InvalidOperationException('Unknown XML namespace prefix: \'' . $prefix . '\'.' . ' Use the addNamespace method to add support for this prefix.'); else $attributes['xmlns:' . $prefix] = $this->namespaces[$prefix]; } if (!empty($defaultNamespace)) $attributes['xmlns'] = $defaultNamespace; $out .= $this->makeNode($tagName, '', $attributes, true); return $out; } private function makeFooter() { if ($this->version == Feed::RSS2) { return '</channel>' . PHP_EOL . '</rss>'; } elseif ($this->version == Feed::RSS1) { return '</rdf:RDF>'; } elseif ($this->version == Feed::ATOM) { return '</feed>'; } } private function makeNode($tagName, $tagContent, ?array $attributes = null, $omitEndTag = false) { $nodeText = ''; $attrText = ''; if ($attributes != null) { foreach ($attributes as $key => $value) { $value = self::filterInvalidXMLChars($value); $value = htmlspecialchars($value); $attrText .= " $key=\"$value\""; } } $attrText .= (in_array($tagName, $this->CDATAEncoding) && $this->version == Feed::ATOM) ? ' type="html"' : ''; $nodeText .= "<{$tagName}{$attrText}>"; $nodeText .= (in_array($tagName, $this->CDATAEncoding)) ? '<![CDATA[' : ''; if (is_array($tagContent)) { foreach ($tagContent as $key => $value) { if (is_array($value)) { $nodeText .= PHP_EOL; foreach ($value as $subValue) { $nodeText .= $this->makeNode($key, $subValue); } } else if (is_string($value)) { $nodeText .= $this->makeNode($key, $value); } else { throw new \InvalidArgumentException("Unknown node-value type for $key"); } } } else { $tagContent = self::filterInvalidXMLChars($tagContent); $nodeText .= (in_array($tagName, $this->CDATAEncoding)) ? $this->sanitizeCDATA($tagContent) : htmlspecialchars($tagContent); } $nodeText .= (in_array($tagName, $this->CDATAEncoding)) ? ']]>' : ''; if (!$omitEndTag) $nodeText .= "</$tagName>"; $nodeText .= PHP_EOL; return $nodeText; } private function makeChannels() { $out = ''; switch ($this->version) { case Feed::RSS2: $out .= '<channel>' . PHP_EOL; break; case Feed::RSS1: $out .= (isset($this->data['ChannelAbout']))? "<channel rdf:about=\"{$this->data['ChannelAbout']}\">" : "<channel rdf:about=\"{$this->channels['link']['content']}\">"; break; } foreach ($this->channels as $key => $value) { if ($this->version == Feed::ATOM && strncmp($key, 'atom', 4) == 0) { $key = substr($key, 5); } if (!array_key_exists('content', $value)) { foreach ($value as $singleElement) { $out .= $this->makeNode($key, $singleElement['content'], $singleElement['attributes']); } } else { $out .= $this->makeNode($key, $value['content'], $value['attributes']); } } if ($this->version == Feed::RSS1) { $out .= "<items>" . PHP_EOL . "<rdf:Seq>" . PHP_EOL; foreach ($this->items as $item) { $thisItems = $item->getElements(); $out .= "<rdf:li resource=\"{$thisItems['link']['content']}\"/>" . PHP_EOL; } $out .= "</rdf:Seq>" . PHP_EOL . "</items>" . PHP_EOL . "</channel>" . PHP_EOL; if (array_key_exists('Image', $this->data)) $out .= $this->makeNode('image', $this->data['Image'], array('rdf:about' => $this->data['Image']['url'])); } else if ($this->version == Feed::ATOM) { $out .= $this->makeNode('id', Feed::uuid($this->channels['title']['content'], 'urn:uuid:')); } return $out; } private function makeItems() { $out = ''; foreach ($this->items as $item) { $thisItems = $item->getElements(); if ($this->version == Feed::RSS1) $out .= $this->startItem($thisItems['link']['content']); else $out .= $this->startItem(); foreach ($thisItems as $feedItem) { $name = $feedItem['name']; if ($this->version == Feed::ATOM && strncmp($name, 'atom', 4) == 0) $name = substr($name, 5); $out .= $this->makeNode($name, $feedItem['content'], $feedItem['attributes']); } $out .= $this->endItem(); } return $out; } private function startItem($about = false) { $out = ''; if ($this->version == Feed::RSS2) { $out .= '<item>' . PHP_EOL; } elseif ($this->version == Feed::RSS1) { if ($about) { $out .= "<item rdf:about=\"$about\">" . PHP_EOL; } else { throw new InvalidOperationException("Missing data for about attribute. Call setChannelAbout method."); } } elseif ($this->version == Feed::ATOM) { $out .= "<entry>" . PHP_EOL; } return $out; } private function endItem() { if ($this->version == Feed::RSS2 || $this->version == Feed::RSS1) { return '</item>' . PHP_EOL; } elseif ($this->version == Feed::ATOM) { return '</entry>' . PHP_EOL; } } private function sanitizeCDATA($text) { $text = str_replace("]]>", "]]&gt;", $text); $text = str_replace("<![CDATA[", "&lt;![CDATA[", $text); return $text; } }
